// next/image loader for Cloudflare Workers Free: no request-time transformation. Local /photos/*.jpg|png map to the
// WebP widths pre-generated by scripts/build-photo-variants.mjs; anything else (and dev, where the variants are not
// built) is served as-is.
const WIDTHS = [384, 640, 828, 1200] as const;
const PHOTO = /^\/photos\/([\w-]+)\.(?:jpe?g|png)$/i;

export function photoVariantUrl(src: string, width: number): string | null {
  const name = PHOTO.exec(src)?.[1];
  if (!name) return null;
  const target = WIDTHS.find((w) => w >= width) ?? WIDTHS[WIDTHS.length - 1];
  return `/photos/w/${name}-${target}.webp`;
}

export default function imageLoader({ src, width }: { src: string; width: number; quality?: number }): string {
  if (process.env.NODE_ENV !== "production") return src;
  return photoVariantUrl(src, width) ?? src;
}
